    cols = len(grid[0])
    background = grid[0][0]
    visited = [[False]*cols for _ in range(rows)]
    result = [row[:] for row in grid]

    def get_component_cells(r, c, color):
        queue = [(r, c)]
        cells = [(r, c)]
        while queue:
            rr, cc = queue.pop(0)
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = rr+dr, cc+dc
                if (0 <= nr < rows and 0 <= nc < cols and 
